SELECT EXISTS (
SELECT 1
FROM msf_request mr
INNER JOIN msf_request_cstmr mrc
ON mr.request_key = mrc.request_key
WHERE mr.request_key::text = #{requestKey}


    AND (
    mrc.cstmr_native_birth::text = #{password}
    OR mrc.cstmr_foreigner_birth::text = #{password}
    )


    AND mrc.cstmr_juridical_biz_no::text = #{password}


    AND (
    (mrc.cstmr_juridical_biz_no IS NULL
    OR TRIM(mrc.cstmr_juridical_biz_no::text) = '')
    AND LEFT(mrc.cstmr_juridical_rrn::text, 6) = #{password}
    )


    AND 1 = 0


)

